                L1NodeId,
                L1Label,
                L1SortOrder,
                L2NodeId,
                L2Label,
                L2SortOrder,
                L3NodeId,
                L3Label,
                L3SortOrder,
                Rows
            ),
            StartCol,
            Min(Rows, LocalColIndex),
            EndCol,
            Max(Rows, LocalColIndex),
            ColCount,
            CountRows(Rows),
            StartX,
            (Min(Rows, LocalColIndex) - 1) * varPHR_ColW,
            WidthPx,
            CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 4) Build active L2 groups ordered by real horizontal position
ClearCollect(
    colPHR_HeaderL2_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                L2NodeId,
                L2Label,
                L2SortOrder,
                Rows
            ),
            StartCol,
            Min(Rows, LocalColIndex),
            EndCol,
            Max(Rows, LocalColIndex),
            ColCount,
            CountRows(Rows),
            StartX,
            (Min(Rows, LocalColIndex) - 1) * varPHR_ColW,
            WidthPx,
            CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 5) Build active L1 group ordered by real horizontal position
ClearCollect(
    colPHR_HeaderL1_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                Rows
            ),
            StartCol,
            Min(Rows, LocalColIndex),
            EndCol,
            Max(Rows, LocalColIndex),
            ColCount,
            CountRows(Rows),
            StartX,
            0,
            WidthPx,
            CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 6) Build active row cells
Clear(colPHR_RowCells_Active);

ForAll(
    colPHR_Subsystems As s,
    Collect(
        colPHR_RowCells_Active,
        AddColumns(
            colPHR_HeaderL4_Active As h,
            SubsystemCode,
            s.SubsystemCode,
            RowNo,
            s.RowNo,
            CellValue,
            Coalesce(
                LookUp(
                    colPHR_Metrics,
                    Text(SubsystemCode) = Text(s.SubsystemCode) &&
                    Text(MetricKey) = Text(h.MetricKey),
                    MetricValue
                ),
                0
            )
        )
    )
);

// 7) Recalculate active widths
Set(
    varPHR_DataColsWidth_Active,
    Max(
        CountRows(colPHR_HeaderL4_Active) * varPHR_ColW,
        varPHR_ColW
    )
);

Set(
    varPHR_TotalGridWidth_Active,
    varPHR_StatusW + varPHR_SubsysW + varPHR_ActionsW + varPHR_DataColsWidth_Active
);

// 8) Reset horizontal scroll
Reset(sldPHR_HOffset);

Rules.InvariantScript:
Set(varOps_IsLoading, true);
Set(varOps_Error, "");

IfError(
    WarRoom_Operations_RefreshCellCache.Run(
        Text(varProjectId),
        If(IsBlank(varOps_FilterSubsystem), "", Text(varOps_FilterSubsystem)),
        true
    ),
    Set(varOps_Error, FirstError.Message);
    Notify("Refresh cache error: " & varOps_Error, NotificationType.Error)
);

Set(varOps_IsLoading, false);

If(
    IsBlank(varProjectId) || !IsNumeric(Text(varProjectId)),

    Notify("Select a valid project first.", NotificationType.Warning);
    Set(varPHR_IsLoading, false);
    Set(varOps_IsLoading, false);

    Set(varGlobalLoading, false);
    Set(varGlobalLoadingMsg, "");
    Set(varGlobalLoadingSubMsg, "");
    Set(varGlobalLoadingScope, "")
    
    ,

    If(
        varPHR_IsLoading || varOps_IsLoading,

        Notify("Overview is already loading.", NotificationType.Information),

        Set(varPHR_IsLoading, true);
        Set(varOps_IsLoading, true);
        Set(varGlobalLoading, true);
        Set(varGlobalLoadingMsg, "Loading Overview...");
        Set(varGlobalLoadingSubMsg, "Building Project Handover Report");
        Set(varGlobalLoadingScope, "OVERVIEW");

        Set(varPHR_LastErrorMessage, "");
        Set(varOverviewNoConfig, false);
        Set(varOverviewNoData, false);
        Set(varProjectHasPHRData, false);
        Set(varPHR_OverviewLoaded, false);

        Clear(colPHR_Subsystems);
        Clear(colPHR_Metrics);
        Clear(colPHR_Headers);
        Clear(colPHR_RowCells);
        Clear(colPHR_RowCells_Active);

        Clear(colPHR_HeaderL4);
        Clear(colPHR_HeaderL4Indexed);
        Clear(colPHR_HeaderL3Base);
        Clear(colPHR_HeaderL2Base);
        Clear(colPHR_HeaderL1Base);
        Clear(colPHR_TabsL1);
        Clear(colPHR_HeaderL4_Active);
        Clear(colPHR_HeaderL3_Active);
        Clear(colPHR_HeaderL2_Active);
        Clear(colPHR_HeaderL1_Active);

        Set(varPHR_Page, Coalesce(varPHR_Page, 1));
        Set(varPHR_PageSize, Coalesce(varPHR_PageSize, 50));

        Set(varPHR_HeaderH1, 26);
        Set(varPHR_HeaderH2, 24);
        Set(varPHR_HeaderH3, 30);
        Set(varPHR_HeaderH4, 36);
        Set(varPHR_RowH, 44);

        Set(varPHR_ColW, 66);
        Set(varPHR_StatusW, 52);
        Set(varPHR_SubsysW, 190);
        Set(varPHR_ActionsW, 90);
        Set(varPHR_LeftFixedW, varPHR_StatusW + varPHR_SubsysW + varPHR_ActionsW);

        Set(varPHR_SelectedL1NodeId, "");
        Set(varPHR_SelectedL1Label, "");

        IfError(
            With(
                {
                    resp: Warroom_PHR_GetPage.Run(
                        Value(varProjectId),
                        If(IsBlank(varFilter_Subsystem), "", Text(varFilter_Subsystem)),
                        Value(varPHR_Page),
                        Value(varPHR_PageSize)
                    )
                },
                With(
                    {
                        raw: Coalesce(resp.result, "{}"),
                        obj: ParseJSON(Coalesce(resp.result, "{}"))
                    },
                    Set(varPHR_LastRawResult, raw);

                    ClearCollect(
                        colPHR_Subsystems_Base,
                        ForAll(
                            Table(obj.subsystems),
                            {
                                SubsystemCode: Text(Value.SubsystemCode)
                            }
                        )
                    );

                    ClearCollect(
                        colPHR_Subsystems,
                        ForAll(
                            Sequence(CountRows(colPHR_Subsystems_Base)),
                            With(
                                {
                                    rowIndex: Value,
                                    rowRecord: Last(FirstN(colPHR_Subsystems_Base, Value))
                                },
                                {
                                    RowNo: rowIndex,
                                    SubsystemCode: rowRecord.SubsystemCode
                                }
                            )
                        )
                    );

                    ClearCollect(
                        colSubsystems,
                        SortByColumns(
                            ForAll(
                                colPHR_Subsystems,
                                {
                                    Code: Text(SubsystemCode)
                                }
                            ),
                            "Code",
                            SortOrder.Ascending
                        )
                    );

                    ClearCollect(
                        colPHR_Metrics,
                        ForAll(
                            Table(obj.metrics),
                            {
                                SubsystemCode: Text(Value.SubsystemCode),
                                MetricKey: Text(Value.MetricKey),
                                MetricValue:
                                    If(
                                        IsBlank(Text(Value.MetricValue)) || Text(Value.MetricValue) = "null",
                                        0,
                                        Value(Text(Value.MetricValue))
                                    )
                            }
                        )
                    );

                    ClearCollect(
                        colPHR_Headers,
                        ForAll(
                            Table(obj.headers),
                            {
                                L1NodeId: Text(Value.L1NodeId),
                                L1Label: Text(Value.L1Label),
                                L1SortOrder:
                                    If(
                                        IsBlank(Text(Value.L1SortOrder)) || Text(Value.L1SortOrder) = "null",
                                        0,
                                        Value(Text(Value.L1SortOrder))
                                    ),

                                L2NodeId: Text(Value.L2NodeId),
                                L2Label: Text(Value.L2Label),
                                L2SortOrder:
                                    If(
                                        IsBlank(Text(Value.L2SortOrder)) || Text(Value.L2SortOrder) = "null",
                                        0,
                                        Value(Text(Value.L2SortOrder))
                                    ),

                                L3NodeId: Text(Value.L3NodeId),
                                L3Label: Text(Value.L3Label),
                                L3SortOrder:
                                    If(
                                        IsBlank(Text(Value.L3SortOrder)) || Text(Value.L3SortOrder) = "null",
                                        0,
                                        Value(Text(Value.L3SortOrder))
                                    ),

                                MetricKey: Text(Value.MetricKey),
                                MetricSqlKey: Text(Value.MetricSqlKey),
                                MetricLabel: Text(Value.MetricLabel),
                                MetricSortOrder:
                                    If(
                                        IsBlank(Text(Value.MetricSortOrder)) || Text(Value.MetricSortOrder) = "null",
                                        0,
                                        Value(Text(Value.MetricSortOrder))
                                    )
                            }
                        )
                    );

                    Set(
                        varPHR_TotalCount,
                        If(
                            IsBlank(Text(obj.totalCount)) || Text(obj.totalCount) = "null",
                            CountRows(colPHR_Subsystems),
                            Value(Text(obj.totalCount))
                        )
                    )
                )
            ),

            Set(varPHR_LastErrorMessage, FirstError.Message);
            Set(varOverviewNoConfig, true);
            Set(varOverviewNoData, true);
            Clear(colPHR_Subsystems);
            Clear(colPHR_Metrics);
            Clear(colPHR_Headers)
        );

        If(
            IsBlank(varPHR_LastErrorMessage) &&
            CountRows(colPHR_Subsystems) > 0 &&
            CountRows(colPHR_Headers) > 0,

            ClearCollect(
                colPHR_HeaderL4,
                SortByColumns(
                    colPHR_Headers,
                    "L1SortOrder", SortOrder.Ascending,
                    "L1Label", SortOrder.Ascending,
                    "L2SortOrder", SortOrder.Ascending,
                    "L2Label", SortOrder.Ascending,
                    "L3SortOrder", SortOrder.Ascending,
                    "L3Label", SortOrder.Ascending,
                    "MetricSortOrder", SortOrder.Ascending,
                    "MetricKey", SortOrder.Ascending
                )
            );

            Clear(colPHR_HeaderL4Indexed);

            ForAll(
                Sequence(CountRows(colPHR_HeaderL4)) As seq,
                Collect(
                    colPHR_HeaderL4Indexed,
                    Patch(
                        Last(FirstN(colPHR_HeaderL4, seq.Value)),
                        {
                            ColIndex: seq.Value,
                            StartX: (seq.Value - 1) * varPHR_ColW,
                            WidthPx: varPHR_ColW
                        }
                    )
                )
            );

            ClearCollect(
                colPHR_HeaderL3Base,
                SortByColumns(
                    AddColumns(
                        GroupBy(
                            colPHR_HeaderL4Indexed,
                            L1NodeId,
                            L1Label,
                            L1SortOrder,
                            L2NodeId,
                            L2Label,
                            L2SortOrder,
                            L3NodeId,
                            L3Label,
                            L3SortOrder,
                            Rows
                        ),
                        StartCol, Min(Rows, ColIndex),
                        EndCol, Max(Rows, ColIndex),
                        ColCount, CountRows(Rows),
                        StartX, (Min(Rows, ColIndex) - 1) * varPHR_ColW,
                        WidthPx, CountRows(Rows) * varPHR_ColW
                    ),
                    "L1SortOrder", SortOrder.Ascending,
                    "L1Label", SortOrder.Ascending,
                    "L2SortOrder", SortOrder.Ascending,
                    "L2Label", SortOrder.Ascending,
                    "L3SortOrder", SortOrder.Ascending,
                    "L3Label", SortOrder.Ascending
                )
            );

            ClearCollect(
                colPHR_HeaderL2Base,
                SortByColumns(
                    AddColumns(
                        GroupBy(
                            colPHR_HeaderL4Indexed,
                            L1NodeId,
                            L1Label,
                            L1SortOrder,
                            L2NodeId,
                            L2Label,
                            L2SortOrder,
                            Rows
                        ),
                        StartCol, Min(Rows, ColIndex),
                        EndCol, Max(Rows, ColIndex),
                        ColCount, CountRows(Rows),
                        StartX, (Min(Rows, ColIndex) - 1) * varPHR_ColW,
                        WidthPx, CountRows(Rows) * varPHR_ColW
                    ),
                    "L1SortOrder", SortOrder.Ascending,
                    "L1Label", SortOrder.Ascending,
                    "L2SortOrder", SortOrder.Ascending,
                    "L2Label", SortOrder.Ascending
                )
            );

            ClearCollect(
                colPHR_HeaderL1Base,
                SortByColumns(
                    AddColumns(
                        GroupBy(
                            colPHR_HeaderL4Indexed,
                            L1NodeId,
                            L1Label,
                            L1SortOrder,
                            Rows
                        ),
                        StartCol, Min(Rows, ColIndex),
                        EndCol, Max(Rows, ColIndex),
                        ColCount, CountRows(Rows),
                        StartX, (Min(Rows, ColIndex) - 1) * varPHR_ColW,
                        WidthPx, CountRows(Rows) * varPHR_ColW
                    ),
                    "L1SortOrder", SortOrder.Ascending,
                    "L1Label", SortOrder.Ascending
                )
            );

            ClearCollect(
                colPHR_TabsL1,
                AddColumns(
                    SortByColumns(
                        colPHR_HeaderL1Base,
                        "L1SortOrder", SortOrder.Ascending,
                        "L1Label", SortOrder.Ascending
                    ),
                    IsSelected, false
                )
            );

            If(
                CountRows(colPHR_TabsL1) > 0,
                Set(varPHR_SelectedL1NodeId, First(colPHR_TabsL1).L1NodeId);
                Set(varPHR_SelectedL1Label, First(colPHR_TabsL1).L1Label)
            );

            Clear(colPHR_RowCells);

            ForAll(
                colPHR_Subsystems As s,
                Collect(
                    colPHR_RowCells,
                    AddColumns(
                        colPHR_HeaderL4Indexed As h,
                        SubsystemCode, s.SubsystemCode,
                        CellValue,
                        Coalesce(
                            LookUp(
                                colPHR_Metrics,
                                SubsystemCode = s.SubsystemCode &&
                                MetricKey = h.MetricKey,
                                MetricValue
                            ),
                            0
                        )
                    )
                )
            );

            Set(varPHR_DataColsWidth, CountRows(colPHR_HeaderL4Indexed) * varPHR_ColW);
            Set(varPHR_TotalGridWidth, varPHR_SubsysW + varPHR_ActionsW + varPHR_DataColsWidth);

            If(
                !IsBlank(varPHR_SelectedL1NodeId),
                Select(btnPHR_RebuildActiveTab)
            );

            Set(varProjectHasPHRData, true);
            Set(varOverviewNoConfig, false);
            Set(varOverviewNoData, false),

            If(
                IsBlank(varPHR_LastErrorMessage),

                Set(varProjectHasPHRData, false);
                Set(varOverviewNoData, true);

                If(
                    CountRows(colPHR_Headers) = 0,
                    Set(varOverviewNoConfig, true),
                    Set(varOverviewNoConfig, false)
                )
            )
        );

        Set(varPHR_IsLoading, false);
        Set(varOps_IsLoading, false);
        
        Set(varGlobalLoading, false);
        Set(varGlobalLoadingMsg, "");
        Set(varGlobalLoadingSubMsg, "");
        Set(varGlobalLoadingScope, "");

        Set(varPHR_OverviewLoaded, true);
        Set(varPHR_LastRefresh, Now())
    )
)

Set(varPHR_StartTabTimer, false);

Set(varPHR_SelectedL1NodeId, varPHR_PendingL1NodeId);
Set(varPHR_SelectedL1Label, varPHR_PendingL1Label);

Select(btnPHR_RebuildActiveTab);

Set(varPHR_TabSwitching, false);
Set(varPHR_TabSwitchMsg, "")
